def summarize_ints(nums: list[int]) -> str:
    """See SPEC.md."""
    uniq = sorted(set(nums))
    parts: list[str] = []
    i = 0
    while i < len(uniq):
        j = i
        while j + 1 < len(uniq) and uniq[j + 1] == uniq[j] + 1:
            j += 1
        if j - i + 1 >= 4:
            lo, hi = uniq[i], uniq[j]
            lo_s = f"({lo})" if lo < 0 else str(lo)
            hi_s = f"({hi})" if hi < 0 else str(hi)
            parts.append(f"{lo_s}-{hi_s}")
        else:
            parts.extend(str(n) for n in uniq[i:j + 1])
        i = j + 1
    return ",".join(parts)

